                var evpDiversity = [0, 0, 0.3, 1.5][d.strategicChoice];

                var hireQuality = [0, 55, 70, 88][d.investmentLevel];
                var newHires = [0, 85, 70, 55][d.investmentLevel];
                var selectionCost = [0, 400000, 650000, 950000][d.investmentLevel];

                var onboardQuality = [0, 40, 65, 85][d.approach];
                var onboardCost = [0, 200000, 450000, 720000][d.approach];

                var channelBonus = d.budgetAllocation * 0.1;

                quarterCost = 2400000 + selectionCost + onboardCost;

                ds.brandScore = Math.min(100, Math.round(ds.brandScore + evpBrand + channelBonus));
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + evpENPS + (onboardQuality - 50) * 0.08));
                ds.diversityIndex = Math.min(10, Math.round((ds.diversityIndex + evpDiversity) * 10) / 10);
                ds.onboardingQuality = onboardQuality;
                ds.hireQuality = hireQuality;
                ds.employeeCount += newHires;
                ds.turnoverRate = Math.max(5, Math.round((ds.turnoverRate - (onboardQuality - 30) * 0.06) * 10) / 10);
                ds.budget -= quarterCost;

                quarterScore = Math.round(
                    (ds.brandScore / 100) * 30 +
                    (hireQuality / 100) * 35 +
                    (onboardQuality / 100) * 25 +
                    (d.budgetAllocation / 100) * 10
                );

            } else if (period === 2) {
                var capBonus = [0, 8, 4, 6][d.strategicChoice];
                var careerENPS = [0, 4, 1, 6][d.strategicChoice];
                var careerDiv = [0, 0.2, 0, 0.5][d.strategicChoice];

                var mgrBonus = [0, 0, 10, 25][d.investmentLevel];
                var mgrCost = [0, 0, 268800, 1184000][d.investmentLevel];

                var ldCap = [0, 10, 7, 8][d.approach];
                var ldENPS = [0, 0, 5, 3][d.approach];
                var ldTurnover = [0, 0, -2, -1][d.approach];

                var stratBonus = d.budgetAllocation * 0.12;
                quarterCost = 3800000 + mgrCost;

                ds.capabilityScore = Math.min(100, Math.round(ds.capabilityScore + capBonus + ldCap + stratBonus));
                ds.managerQuality = Math.min(100, Math.round(ds.managerQuality + mgrBonus));
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + careerENPS + ldENPS));
                ds.turnoverRate = Math.max(5, Math.round((ds.turnoverRate + ldTurnover) * 10) / 10);
                ds.diversityIndex = Math.min(10, Math.round((ds.diversityIndex + careerDiv) * 10) / 10);
                ds.budget -= quarterCost;

                if (ds.onboardingQuality < 50) {
                    ds.turnoverRate = Math.round((ds.turnoverRate + 3) * 10) / 10;
                    eventSummary = window.mySimulation.t('event_onboard_debt');
                }

                var revGrowth = Math.round(ds.capabilityScore * 400);
                ds.revenuePerEmployee += revGrowth;

                quarterScore = Math.round(
                    (ds.capabilityScore / 100) * 30 +
                    (ds.managerQuality / 100) * 25 +
                    (Math.max(0, 30 - ds.turnoverRate) / 25) * 25 +
                    (d.budgetAllocation / 100) * 20
                );

            } else if (period === 3) {
                var compTurnover = [0, -5, -2, 1][d.strategicChoice];
                var compCost = [0, 5000000, 2500000, -1000000][d.strategicChoice];
                var compENPS = [0, 3, 1, -2][d.strategicChoice];

                var eqRetention = [0, 2, 5, 3][d.investmentLevel];
                var eqCost = [0, 1200000, 2000000, 800000][d.investmentLevel];

                var retTurnover = [0, -2, -4, -6][d.approach];
                var retENPS = [0, 1, 5, 7][d.approach];
                var retCost = [0, 800000, 500000, 1200000][d.approach];

                var nonMonCost = Math.round(1600000 * (d.budgetAllocation / 100));
                var nonMonENPS = d.budgetAllocation * 0.06;

                if (d.strategicChoice === 3 && d.budgetAllocation > 60) {
                    compTurnover = -2;
                    compENPS = 3;
                }

                quarterCost = (compCost > 0 ? compCost : 0) + eqCost + retCost + nonMonCost;
                if (compCost < 0) ds.budget -= compCost;

                ds.turnoverRate = Math.max(5, Math.round((ds.turnoverRate + compTurnover + retTurnover - eqRetention * 0.3) * 10) / 10);
                ds.eNPS = Math.min(80, Math.round(ds.eNPS + compENPS + retENPS + nonMonENPS));
                ds.budget -= quarterCost;

                if (ds.managerQuality < 50) {
                    ds.eNPS = Math.round(ds.eNPS - 5);
                    ds.turnoverRate = Math.round((ds.turnoverRate + 2) * 10) / 10;
                    eventSummary = window.mySimulation.t('event_manager_debt');
                }

                quarterScore = Math.round(
                    (Math.max(0, 30 - ds.turnoverRate) / 25) * 30 +
                    (Math.max(0, ds.eNPS + 20) / 100) * 30 +
                    (d.budgetAllocation / 100) * 20 +
                    (eqRetention / 5) * 20
                );

            } else if (period === 4) {
                var reducedCount = Math.round(ds.employeeCount * 0.2);
                ds.employeeCount -= reducedCount;

                var legalRisk = [0, 10, 35, 15][d.strategicChoice];
                var capImpact = [0, -12, -3, -2][d.strategicChoice];
                var survBase = [0, 55, 65, 72][d.strategicChoice];

                var sevCost = [0, reducedCount * 15000, reducedCount * 40000, reducedCount * 75000][d.investmentLevel];
                var sevEng = [0, -10, 5, 15][d.investmentLevel];

                var commEng = [0, 20, 8, -5][d.approach];
                var commBrand = [0, 5, -2, -12][d.approach];

                var reEngBonus = d.budgetAllocation * 0.25;
                var reEngCost = Math.round(ds.budget * 0.08 * (d.budgetAllocation / 100));

                var eNPSPenalty = ds.eNPS < 25 ? -10 : 0;
                if (ds.managerQuality < 50) {
                    commEng = Math.round(commEng * 0.6);
                }

                var survivorEng = Math.min(100, Math.max(0, Math.round(survBase + sevEng + commEng + reEngBonus + eNPSPenalty)));

                quarterCost = sevCost + reEngCost;
                ds.budget -= quarterCost;
                ds.capabilityScore = Math.max(0, Math.round(ds.capabilityScore + capImpact));
                ds.brandScore = Math.max(0, Math.min(100, Math.round(ds.brandScore + commBrand - 5)));
                ds.survivorEngagement = survivorEng;
                ds.legalRisk = legalRisk;

                var postTurnover = Math.max(5, Math.round((30 - survivorEng * 0.22) * 10) / 10);
                ds.turnoverRate = postTurnover;
                ds.eNPS = Math.round(survivorEng * 0.7 - 15);

                var legalCost = 0;
                if (legalRisk > 25) {
                    legalCost = Math.round(2400000 * (legalRisk / 100));
                    ds.budget -= legalCost;
                    eventSummary = window.mySimulation.t('event_legal_challenge');
                }

                quarterScore = Math.round(
                    (survivorEng / 100) * 35 +
                    ((100 - legalRisk) / 100) * 20 +
                    ((100 - postTurnover) / 100) * 25 +
                    (d.budgetAllocation / 100) * 20
                );
            }

            ds.scoreHistory.push(quarterScore);
            ds.eNPSHistory.push(ds.eNPS);
            ds.turnoverHistory.push(ds.turnoverRate);
            ds.brandHistory.push(ds.brandScore);

            // overallScore replays the getPerformanceSummary composite formula from the running domainState so far, already 0-100, clamped
            var runTalentQuality = Math.round((ds.scoreHistory[0] || 0) * 0.6 + (ds.scoreHistory[1] || 0) * 0.4);
            var runOrgHealth = Math.round(Math.max(0, ds.eNPS + 20) + Math.max(0, 30 - ds.turnoverRate) * 2);
            var runCapReadiness = ds.capabilityScore || 0;
            var runFinancialEff = Math.round(Math.max(0, ds.budget / 500000));
            var runCrisisResilience = ds.scoreHistory[3] || 0;
            var runComposite = Math.round(
                runTalentQuality * 0.25 +
                Math.min(100, runOrgHealth) * 0.25 +
                runCapReadiness * 0.20 +
                Math.min(100, runFinancialEff) * 0.20 +
                runCrisisResilience * 0.10
            );
            var overallScore = Math.max(0, Math.min(100, runComposite));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var results = {
                period: period,
                quarterScore: quarterScore,
                brandScore: ds.brandScore,
                eNPS: ds.eNPS,
                turnoverRate: ds.turnoverRate,
                capabilityScore: ds.capabilityScore,
                employeeCount: ds.employeeCount,
                budget: ds.budget,
                quarterCost: quarterCost,
                eventSummary: eventSummary
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 400);

            return results;
        }

